}

Method.Source:
/// <summary>
/// WolfA 13.10.21
/// </summary>
/// <param name = "_args">XppPrePostArgs</param>
[PostHandlerFor(tableStr(SalesQuotationLine), tableMethodStr(SalesQuotationLine, modifiedField))]
public static void SalesQuotationLine_Post_onModifiedField(XppPrePostArgs _args)
{
    FieldId fieldId = _args.getArg(identifierStr(_fieldId));
    SalesQuotationLine salesquotationLine = _args.getThis();

    boolean     ok;
    container   conErrorMessage;
    SalesQty    economicBatchSize;

    switch (fieldId)
    {
        case fieldNum(SalesQuotationLine, KCS_CalcPDPPrice) :
            salesquotationLine.KCS_RecalcAfterCalcPDPriceChanged();
            break;

        case fieldNum(SalesQuotationLine, SalesQty):
            // wirtschaftliche Losgröße erreicht?
            [ok, conErrorMessage, economicBatchSize] = NDX_ItemValidity::checkValidityEconomicBatchSize(salesquotationLine.ItemId, salesquotationLine.SalesQty);
            if (!ok)
            {
                conErrorMessage += strfmt("@NDX:NDXItemValidityEconomicBatchSizeIncrease", economicBatchSize);   // Die Angebotsmenge muss auf mindestens [%1] erhöht werden!
                salesquotationLine.SalesQty = economicBatchSize;
                Warning(NDX_ItemValidity::conErrorMessage2ValidityMessage(conErrorMessage));
            }
            break;
        case fieldNum(SalesQuotationLine, ItemId) :
            NDXItemStateTable::ShowInfo(salesquotationLine.ItemId);
            break;
    }
}
